using System.IO; using UnityEditor; using UnityEditor.Build; using UnityEditor.Build.Reporting; using UnityEditor.SceneManagement; using UnityEngine; using UnityEngine.InputSystem.XR; using UnityEngine.XR.ARFoundation; using UnityEngine.XR.ARSubsystems; using Unity.XR.CoreUtils;
namespace BiniarosAR.Editor { public sealed class BiniarosPreBuild:IPreprocessBuildWithReport { public int callbackOrder=>-1000; public void OnPreprocessBuild(BuildReport report)=>BiniarosBuildAndroid.SetupProject(); } public static class BiniarosBuildAndroid { const string ScenePath="Assets/Scenes/BINIAROS_AR.unity"; [MenuItem("BINIAROS/Setup AR Project")] public static void SetupProject(){PlayerSettings.applicationIdentifier="com.biniaros.ar";PlayerSettings.productName="BINIAROS AR";PlayerSettings.companyName="BINIAROS";PlayerSettings.Android.minSdkVersion=AndroidSdkVersions.AndroidApiLevel24;PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android,ScriptingImplementation.IL2CPP);PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;CreateScene();AssetDatabase.SaveAssets();AssetDatabase.Refresh();}
static void CreateScene(){Directory.CreateDirectory("Assets/Scenes");var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var sgo=new GameObject("AR Session");var boot=sgo.AddComponent<BiniarosAR.RuntimeARBootstrap>();var session=sgo.AddComponent<ARSession>();session.enabled=false;sgo.AddComponent<ARInputManager>();var ogo=new GameObject("XR Origin");var origin=ogo.AddComponent<XROrigin>();var ray=ogo.AddComponent<ARRaycastManager>();ray.enabled=false;var planes=ogo.AddComponent<ARPlaneManager>();planes.requestedDetectionMode=PlaneDetectionMode.Horizontal;planes.enabled=false;var off=new GameObject("Camera Offset");off.transform.SetParent(ogo.transform,false);var cgo=new GameObject("Main Camera");cgo.tag="MainCamera";cgo.transform.SetParent(off.transform,false);var cam=cgo.AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.nearClipPlane=.05f;cgo.AddComponent<AudioListener>();var cm=cgo.AddComponent<ARCameraManager>();cm.enabled=false;var cb=cgo.AddComponent<ARCameraBackground>();cb.enabled=false;cgo.AddComponent<TrackedPoseDriver>();origin.CameraFloorOffsetObject=off;origin.Camera=cam;boot.session=session;boot.raycastManager=ray;boot.planeManager=planes;boot.cameraManager=cm;boot.cameraBackground=cb;var perg=CreateRoma();perg.SetActive(false);var mgr=new GameObject("BINIAROS_AR_MANAGER");var plc=mgr.AddComponent<BiniarosAR.ARPlacementController>();plc.raycastManager=ray;plc.planeManager=planes;plc.arCamera=cam;plc.pergolaRoot=perg.transform;var ui=mgr.AddComponent<BiniarosAR.BiniarosRuntimeUI>();ui.placement=plc;ui.pergola=perg.transform;EditorSceneManager.SaveScene(scene,ScenePath);EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(ScenePath,true)};}
static GameObject CreateRoma(){const float w=5.006f,d=4.002f,h=2.723f,p=.14f,bh=.20f;var r=new GameObject("ROMA_AR_1_TO_1");var m=new Material(Shader.Find("Standard"));m.color=new Color(.18f,.19f,.20f,1);void B(string n,Vector3 pos,Vector3 sc){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(r.transform,false);g.transform.localPosition=pos;g.transform.localScale=sc;g.GetComponent<Renderer>().sharedMaterial=m;Object.DestroyImmediate(g.GetComponent<Collider>());}B("Column_FL",new Vector3(-w/2+p/2,h/2,-d/2+p/2),new Vector3(p,h,p));B("Column_FR",new Vector3(w/2-p/2,h/2,-d/2+p/2),new Vector3(p,h,p));B("Column_RL",new Vector3(-w/2+p/2,h/2,d/2-p/2),new Vector3(p,h,p));B("Column_RR",new Vector3(w/2-p/2,h/2,d/2-p/2),new Vector3(p,h,p));float y=h-bh/2;B("Beam_F",new Vector3(0,y,-d/2+p/2),new Vector3(w,bh,p));B("Beam_B",new Vector3(0,y,d/2-p/2),new Vector3(w,bh,p));B("Beam_L",new Vector3(-w/2+p/2,y,0),new Vector3(p,bh,d));B("Beam_R",new Vector3(w/2-p/2,y,0),new Vector3(p,bh,d));int n=24;float u=d-.34f,st=u/n,ly=h-bh-.045f;for(int i=0;i<n;i++)B("Louver_"+(i+1).ToString("00"),new Vector3(0,ly,-u/2+st*(i+.5f)),new Vector3(w-.34f,.045f,st*.8f));return r;} } }